  .inputValidator((d) => z.object({ query: z.string().min(1).max(400) }).parse(d))
  .handler(async ({ data }) => {
    // 1. SKILL — pull live web/search signal for the topic.
    const sk = await fetch("https://api.aisa.one/v1/skills/aisa-tavily-search", {
